using Microsoft.AspNetCore.Mvc;
using System;
using System.Security.Cryptography;
using System.Text;

namespace InventoryApi.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class InventoryController : ControllerBase
    {
        // Calculates total price for bulk orders
        [HttpPost("calculate-bulk")]
        public IActionResult CalculateBulkOrder([FromBody] BulkOrderRequest request)
        {
            if (request == null || request.Items == null)
                return BadRequest("Invalid request");

            int totalCostCents = 0;

            foreach (var item in request.Items)
            {
                if (item.Quantity <= 0 || item.UnitPriceCents <= 0)
                    return BadRequest("Quantity and price must be positive");

                // Integer overflow vulnerability: no checked arithmetic
                // An attacker can supply values where Quantity * UnitPriceCents > Int32.MaxValue
                int itemTotal = item.Quantity * item.UnitPriceCents;
                totalCostCents += itemTotal;
            }

            // Apply bulk discount: 10% off if total exceeds $1000 (100000 cents)
            int discount = 0;
            if (totalCostCents > 100000)
            {
                discount = totalCostCents / 10;
            }

            int finalCostCents = totalCostCents - discount;

            // If overflow causes negative total, customer gets credited
            return Ok(new BulkOrderResponse
            {
                TotalBeforeDiscount = totalCostCents,
                Discount = discount,
                FinalTotalCents = finalCostCents,
                OrderId = GenerateOrderId()
            });
        }

        // Processes payment - negative amounts trigger refund flow
        [HttpPost("process-payment")]
        public IActionResult ProcessPayment([FromBody] PaymentRequest request)
        {
            if (request.AmountCents < 0)
            {
                // Refund path - triggered by integer overflow producing negative total
                return Ok(new { Status = "REFUND_ISSUED", Amount = Math.Abs(request.AmountCents) });
            }

            return Ok(new { Status = "PAYMENT_PROCESSED", Amount = request.AmountCents });
        }

        private string GenerateOrderId()
        {
            byte[] bytes = new byte[16];
            RandomNumberGenerator.Fill(bytes);
            return Convert.ToHexString(bytes);
        }
    }

    public class BulkOrderRequest
    {
        public OrderItem[] Items { get; set; }
    }

    public class OrderItem
    {
        public int Quantity { get; set; }
        public int UnitPriceCents { get; set; }
    }

    public class BulkOrderResponse
    {
        public int TotalBeforeDiscount { get; set; }
        public int Discount { get; set; }
        public int FinalTotalCents { get; set; }
        public string OrderId { get; set; }
    }

    public class PaymentRequest
    {
        public int AmountCents { get; set; }
        public string OrderId { get; set; }
    }
}
